#!/usr/bin/env python3
from __future__ import annotations

import inspect
import platform
import sys
import types
from pathlib import Path


def _run_impl(source: str, impl_name: str) -> int:
    module_name = f'{__name__}.{impl_name}'
    module = types.ModuleType(module_name)
    module.__file__ = str(Path(__file__).resolve())
    sys.modules[module_name] = module
    namespace = module.__dict__
    exec(compile(source, str(Path(__file__).resolve()), 'exec'), namespace, namespace)
    main_fn = namespace.get('main')
    if not callable(main_fn):
        raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_bench' does not define main()")
    sig = inspect.signature(main_fn)
    if len(sig.parameters) == 0:
        return int(main_fn())
    if len(sig.parameters) == 1:
        return int(main_fn(sys.argv))
    raise RuntimeError(f"Selected implementation '{impl_name}' for 'genai_bench' has unsupported main() signature")


def main() -> int:
    if platform.system().strip().lower().startswith('win'):
        return _run_impl(_WINDOWS_IMPL, 'windows')
    return _run_impl(_LINUX_IMPL, 'linux')


_LINUX_IMPL = 'from __future__ import annotations\n\nimport os\nimport subprocess\nfrom datetime import datetime\nfrom pathlib import Path\n\nfrom _linux_common import CONFIG_FILE, PROJECT_ROOT, load_config, resolve_path, to_bool\n\n\ndef _as_int(value: object, label: str) -> int:\n\ttry:\n\t\treturn int(str(value))\n\texcept Exception as exc:\n\t\traise ValueError(f"{label} must be an integer") from exc\n\n\ndef main() -> int:\n\tif not CONFIG_FILE.is_file():\n\t\tprint(f"Error: {CONFIG_FILE} not found")\n\t\treturn 1\n\n\tcfg = load_config()\n\tbuild_dir = cfg.get("build_dir")\n\tif not build_dir:\n\t\tprint(f"Error: Missing build_dir in {CONFIG_FILE}")\n\t\treturn 1\n\n\tbuild_dir_p = resolve_path(str(build_dir))\n\tbench_script = build_dir_p / "openvino.genai" / "tools" / "llm_bench" / "benchmark.py"\n\tvenv_python = build_dir_p / "openvino.genai" / "tools" / "llm_bench" / "python-env" / "bin" / "python"\n\tif not bench_script.is_file():\n\t\tprint(f"Error: Missing benchmark script at {bench_script}")\n\t\treturn 1\n\tif not venv_python.is_file():\n\t\tprint(f"Error: Missing GenAI Python executable at {venv_python}")\n\t\tprint("Run SCRIPTS/genai_build.py first to create the environment.")\n\t\treturn 1\n\n\tir_root = cfg.get("ir_dir")\n\tif not ir_root:\n\t\tprint(f"Error: Missing ir_dir in {CONFIG_FILE}")\n\t\treturn 1\n\tmodels_root = resolve_path(str(ir_root))\n\tif not models_root.is_dir():\n\t\tprint(f"Error: Models root not found at {models_root}")\n\t\treturn 1\n\n\tresults_dir_raw = cfg.get("results_dir")\n\tif not results_dir_raw:\n\t\tprint(f"Error: Missing results_dir in {CONFIG_FILE}")\n\t\treturn 1\n\tresults_dir = resolve_path(str(results_dir_raw))\n\tresults_dir.mkdir(parents=True, exist_ok=True)\n\n\tgenai_cfg = ((cfg.get("genai") or {}).get("benchmark") or {})\n\ttry:\n\t\tinitial_content_length = _as_int(genai_cfg.get("initial_content_length"), "genai.benchmark.initial_content_length")\n\t\titerations = _as_int(genai_cfg.get("iterations"), "genai.benchmark.iterations")\n\t\tmax_context = _as_int(genai_cfg.get("max_context"), "genai.benchmark.max_context")\n\texcept ValueError as err:\n\t\tprint(f"Error: {err}")\n\t\treturn 1\n\n\tprompt = str(genai_cfg.get("prompt") or "").strip()\n\tprompt_file = str(genai_cfg.get("prompt_file") or "").strip()\n\tprompt_args: list[str]\n\tif prompt:\n\t\tprompt_args = ["-p", prompt]\n\telse:\n\t\tif not prompt_file:\n\t\t\tprint("Error: genai.benchmark.prompt is empty and genai.benchmark.prompt_file is not configured")\n\t\t\treturn 1\n\t\tprompt_path = resolve_path(prompt_file)\n\t\tif not prompt_path.is_file():\n\t\t\tprint(f"Error: Prompt file not found at {prompt_path}")\n\t\t\treturn 1\n\t\tprompt_args = ["-pf", str(prompt_path)]\n\n\trun_matrix = cfg.get("run_matrix") or {}\n\trm_devs = run_matrix.get("devices") or {}\n\tdefaults_devs = [str(d).strip().upper() for d in (cfg.get("defaults", {}).get("devices") or []) if str(d).strip()]\n\n\tselected: list[str] = []\n\tif any(k in rm_devs for k in ("gpu", "npu")):\n\t\tif to_bool(rm_devs.get("gpu")) and to_bool((run_matrix.get("gpu") or {}).get("ov_genai_ir_gpu")):\n\t\t\tselected.append("GPU")\n\t\telif to_bool(rm_devs.get("gpu")):\n\t\t\tprint("Warning: run_matrix.devices.gpu is true but run_matrix.gpu.ov_genai_ir_gpu is false; skipping GPU for genai benchmark.")\n\n\t\tif to_bool(rm_devs.get("npu")) and to_bool((run_matrix.get("npu") or {}).get("ov_genai_ir_npu")):\n\t\t\tselected.append("NPU")\n\t\telif to_bool(rm_devs.get("npu")):\n\t\t\tprint("Warning: run_matrix.devices.npu is true but run_matrix.npu.ov_genai_ir_npu is false; skipping NPU for genai benchmark.")\n\telse:\n\t\tfor d in defaults_devs:\n\t\t\tif d in {"GPU", "NPU"} and d not in selected:\n\t\t\t\tselected.append(d)\n\n\tif not selected:\n\t\tprint("Error: No supported genai devices selected. Supported: GPU, NPU")\n\t\treturn 1\n\n\tir_models = [str(m).strip() for m in (((cfg.get("ir_models") or {}).get("models") or [])) if str(m).strip()]\n\tif not ir_models:\n\t\tprint(f"Error: No models listed under ir_models.models in {CONFIG_FILE}")\n\t\treturn 1\n\n\tout_file = results_dir / f"genaibench_{datetime.now().strftime(\'%Y%m%d_%H%M%S\')}.txt"\n\tprint(f"Saving all run outputs to: {out_file}")\n\n\ttotal_runs = 0\n\tenv = dict(os.environ)\n\n\twith out_file.open("a", encoding="utf-8") as out:\n\t\tfor device in ("GPU", "NPU"):\n\t\t\tif device not in selected:\n\t\t\t\tcontinue\n\n\t\t\tmodel_dirs: list[Path] = []\n\t\t\tfor model_id in ir_models:\n\t\t\t\tstripped = model_id.split("/", 1)[1] if "/" in model_id else model_id\n\t\t\t\tsafe_name = stripped.replace("/", "__")\n\t\t\t\tmodel_xml = models_root / device / safe_name / "openvino_model.xml"\n\t\t\t\tif model_xml.is_file():\n\t\t\t\t\tmodel_dirs.append(model_xml.parent)\n\t\t\t\telse:\n\t\t\t\t\tmsg = (\n\t\t\t\t\t\t"------------------------------------------------\\n"\n\t\t\t\t\t\tf">> Config-listed {device} model not found: {model_id}\\n"\n\t\t\t\t\t\tf">> Expected IR path: {model_xml}\\n"\n\t\t\t\t\t\t"------------------------------------------------\\n"\n\t\t\t\t\t)\n\t\t\t\t\tprint(msg, end="")\n\t\t\t\t\tout.write(msg)\n\n\t\t\tif not model_dirs:\n\t\t\t\tmsg = (\n\t\t\t\t\t"------------------------------------------------\\n"\n\t\t\t\t\tf">> No config-listed {device} models found under {models_root}\\n"\n\t\t\t\t\t"------------------------------------------------\\n"\n\t\t\t\t)\n\t\t\t\tprint(msg, end="")\n\t\t\t\tout.write(msg)\n\t\t\t\tcontinue\n\n\t\t\tfor model_dir in model_dirs:\n\t\t\t\tcmd = [\n\t\t\t\t\tstr(venv_python),\n\t\t\t\t\tstr(bench_script),\n\t\t\t\t\t"-ic",\n\t\t\t\t\tstr(initial_content_length),\n\t\t\t\t\t"-n",\n\t\t\t\t\tstr(iterations),\n\t\t\t\t\t*prompt_args,\n\t\t\t\t\t"-d",\n\t\t\t\t\tdevice,\n\t\t\t\t\t"-mc",\n\t\t\t\t\tstr(max_context),\n\t\t\t\t\t"-m",\n\t\t\t\t\tstr(model_dir),\n\t\t\t\t]\n\t\t\t\tbanner = (\n\t\t\t\t\t"------------------------------------------------\\n"\n\t\t\t\t\tf">> Device: {device}\\n"\n\t\t\t\t\tf">> Model Dir: {model_dir}\\n"\n\t\t\t\t\tf">> Executing: {\' \'.join(cmd)}\\n"\n\t\t\t\t)\n\t\t\t\tprint(banner, end="")\n\t\t\t\tout.write(banner)\n\n\t\t\t\tproc = subprocess.run(cmd, text=True, capture_output=True, env=env, cwd=str(PROJECT_ROOT))\n\t\t\t\ttxt = (proc.stdout or "") + (proc.stderr or "")\n\t\t\t\tif txt:\n\t\t\t\t\tprint(txt, end="" if txt.endswith("\\n") else "\\n")\n\t\t\t\t\tout.write(txt)\n\t\t\t\t\tif not txt.endswith("\\n"):\n\t\t\t\t\t\tout.write("\\n")\n\t\t\t\tout.write("------------------------------------------------\\n")\n\t\t\t\tprint("------------------------------------------------")\n\t\t\t\ttotal_runs += 1\n\n\tif total_runs == 0:\n\t\tprint(f"Error: No GPU/NPU OpenVINO model directories found under {models_root}")\n\t\treturn 1\n\n\tprint(f"Completed {total_runs} genai benchmark runs.")\n\tprint(f"Results saved to: {out_file}")\n\treturn 0\n\n\nif __name__ == "__main__":\n\traise SystemExit(main())\n'


_WINDOWS_IMPL = 'from __future__ import annotations\n\nimport os\nfrom datetime import datetime\nfrom pathlib import Path\n\nfrom _windows_common_ import apply_proxy_env_from_config, load_config, project_root, resolve_path, run_cmd\n\n\ndef venv_python(build_dir: Path) -> Path:\n    return build_dir / "openvino.genai" / "tools" / "llm_bench" / "python-env" / "Scripts" / "python.exe"\n\n\ndef main() -> int:\n    root = project_root(__file__)\n    cfg = load_config(root)\n    env = dict(os.environ)\n    apply_proxy_env_from_config(cfg, env)\n\n    build_dir = resolve_path(root, cfg.get("build_dir"), "./BUILD")\n    ir_dir = resolve_path(root, cfg.get("ir_dir"), "./MODELS/ir")\n    results_dir = resolve_path(root, cfg.get("results_dir"), "./RESULTS")\n    results_dir.mkdir(parents=True, exist_ok=True)\n\n    bench_cfg = cfg.get("genai", {}).get("benchmark", {}) or {}\n    ic = str(bench_cfg.get("initial_content_length", 128))\n    iters = str(bench_cfg.get("iterations", 1))\n    prompt = str(bench_cfg.get("prompt", "")).strip()\n    prompt_file = str(bench_cfg.get("prompt_file", "")).strip()\n    mc = str(bench_cfg.get("max_context", 1))\n\n    py = venv_python(build_dir)\n    bench_script = build_dir / "openvino.genai" / "tools" / "llm_bench" / "benchmark.py"\n    if not py.is_file() or not bench_script.is_file():\n        raise RuntimeError("GenAI benchmark prerequisites missing. Run genai_build.py first.")\n\n    out = results_dir / f"genaibench_{datetime.now().strftime(\'%Y%m%d_%H%M%S\')}.txt"\n\n    models = cfg.get("ir_models", {}).get("models", []) or []\n    run_matrix = cfg.get("run_matrix", {}) or {}\n    dev_flags = (run_matrix.get("devices") or {})\n    run_matrix_gpu_raw = dev_flags.get("gpu")\n    run_matrix_npu_raw = dev_flags.get("npu")\n\n    selected_devices: list[str] = []\n    if run_matrix_gpu_raw is not None or run_matrix_npu_raw is not None:\n        if str(run_matrix_gpu_raw).lower() == "true":\n            if str((run_matrix.get("gpu") or {}).get("ov_genai_ir_gpu", "false")).lower() == "true":\n                selected_devices.append("GPU")\n            else:\n                print("Warning: run_matrix.devices.gpu=true but run_matrix.gpu.ov_genai_ir_gpu=false; skipping GPU")\n        if str(run_matrix_npu_raw).lower() == "true":\n            if str((run_matrix.get("npu") or {}).get("ov_genai_ir_npu", "false")).lower() == "true":\n                selected_devices.append("NPU")\n            else:\n                print("Warning: run_matrix.devices.npu=true but run_matrix.npu.ov_genai_ir_npu=false; skipping NPU")\n    else:\n        defaults_devices = (cfg.get("defaults") or {}).get("devices") or []\n        for dev in defaults_devices:\n            norm = str(dev).strip().upper()\n            if norm in {"GPU", "NPU"} and norm not in selected_devices:\n                selected_devices.append(norm)\n\n    if not selected_devices:\n        raise RuntimeError(\n            "No supported GenAI devices selected. Configure run_matrix or defaults.devices with GPU/NPU."\n        )\n\n    prompt_args: list[str]\n    if prompt:\n        prompt_args = ["-p", prompt]\n    elif prompt_file:\n        pf = Path(prompt_file)\n        if not pf.is_absolute():\n            pf = (root / prompt_file).resolve()\n        if not pf.is_file():\n            raise RuntimeError(f"Configured prompt_file does not exist: {pf}")\n        prompt_args = ["-pf", str(pf)]\n    else:\n        raise RuntimeError("Configure genai.benchmark.prompt or prompt_file")\n\n    total = 0\n    with out.open("w", encoding="utf-8") as fh:\n        for device in selected_devices:\n            for model in models:\n                m = str(model).strip()\n                if not m:\n                    continue\n                name = m.split("/", 1)[-1].replace("/", "__")\n                model_dir = ir_dir / device / name\n                model_xml = model_dir / "openvino_model.xml"\n                if not model_xml.is_file():\n                    continue\n                cmd = [\n                    str(py),\n                    str(bench_script),\n                    "-ic",\n                    ic,\n                    "-n",\n                    iters,\n                    *prompt_args,\n                    "-d",\n                    device,\n                    "-mc",\n                    mc,\n                    "-m",\n                    str(model_dir),\n                ]\n                fh.write("------------------------------------------------\\n")\n                fh.write(f">> Device: {device}\\n")\n                fh.write(f">> Model Dir: {model_dir}\\n")\n                fh.flush()\n                proc = run_cmd(cmd, cwd=root, env=env, check=False, capture_output=True)\n                fh.write(proc.stdout or "")\n                fh.write(proc.stderr or "")\n                fh.write("\\n")\n                fh.flush()\n                if proc.returncode != 0:\n                    raise RuntimeError(f"GenAI benchmark failed for {device}/{m}")\n                total += 1\n\n    if total == 0:\n        raise RuntimeError("No GenAI benchmark runs executed (no exported IR models found)")\n\n    print(f"Completed {total} GenAI runs -> {out}")\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'


if __name__ == '__main__':
    raise SystemExit(main())
